   h('td',{class:'n'},h('button',{type:'button',class:'cc-toggle'+(i.enabled?' on':''),role:'switch','aria-checked':String(!!i.enabled),'aria-label':(i.enabled?'Desativar ':'Ativar ')+i.name,disabled:!can(),onclick:()=>apply(i,i.enabled?'disable':'enable')})),
